import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.C59ourEJ.js";const g=JSON.parse('{"title":"Migrating to 3.0","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration.md","filePath":"guide/migration.md","lastUpdated":1795466436000}'),o={name:"guide/migration.md"};function n(d,e,r,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="migrating-to-3-0" tabindex="-1">Migrating to 3.0 <a class="header-anchor" href="#migrating-to-3-0" aria-label="Permalink to &quot;Migrating to 3.0&quot;">​</a></h1><p>Version 3 removes the Hammer.js dependency and changes how the package is built and published. The options are unchanged: a 2.x configuration works as it is.</p><h2 id="hammer-js-is-no-longer-used" tabindex="-1">Hammer.js is no longer used <a class="header-anchor" href="#hammer-js-is-no-longer-used" aria-label="Permalink to &quot;Hammer.js is no longer used&quot;">​</a></h2><p>Pan and pinch gestures are recognized from the browser&#39;s native <a href="https://developer.mozilla.org/en-US/docs/Web/API/Pointer_events" target="_blank" rel="noreferrer">Pointer Events</a>. The plugin has no runtime dependencies.</p><ul><li><p>Remove <code>hammerjs</code> from your dependencies if you installed it only for this plugin.</p></li><li><p>Remove the Hammer.js <code>&lt;script&gt;</code> tag when loading the plugin from a CDN:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://cdn.jsdelivr.net/npm/hammerjs@2.0.8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- no longer needed --&gt;</span></span></code></pre></div></li><li><p>Workarounds for importing Hammer.js in bundlers or during server-side rendering can be removed.</p></li></ul><h3 id="pan-callbacks-receive-a-gesture-event" tabindex="-1">Pan callbacks receive a gesture event <a class="header-anchor" href="#pan-callbacks-receive-a-gesture-event" aria-label="Permalink to &quot;Pan callbacks receive a gesture event&quot;">​</a></h3><p><code>onPanStart</code> and <code>onPanRejected</code> used to receive a Hammer.js event as <code>event</code>. They now receive a plain object with the fields the plugin itself uses:</p><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>center</code></td><td><code>{x, y}</code></td><td>Midpoint of the active pointers, in client coordinates</td></tr><tr><td><code>deltaX</code>, <code>deltaY</code></td><td><code>number</code></td><td>Pan offset in pixels since the gesture started</td></tr><tr><td><code>distance</code></td><td><code>number</code></td><td>Straight-line distance travelled since the gesture started, in pixels</td></tr><tr><td><code>scale</code></td><td><code>number</code></td><td>Pinch scale relative to the start of the gesture (<code>1</code> is unchanged)</td></tr><tr><td><code>pointers</code></td><td><code>{clientX, clientY}[]</code></td><td>The active pointers</td></tr><tr><td><code>target</code></td><td><code>HTMLElement</code></td><td>The canvas</td></tr><tr><td><code>srcEvent</code></td><td><code>PointerEvent</code></td><td>The native event behind the gesture event</td></tr><tr><td><code>pointerType</code></td><td><code>string</code></td><td><code>mouse</code>, <code>touch</code> or <code>pen</code></td></tr></tbody></table><p>Other Hammer.js fields, such as <code>velocity</code>, <code>direction</code> or <code>isFinal</code>, are gone. <code>srcEvent</code> is now a <code>PointerEvent</code> rather than a <code>MouseEvent</code> or <code>TouchEvent</code>.</p><p><code>onZoomStart</code> and <code>onZoomRejected</code> receive the native event, as before for wheel and drag zoom. For a pinch they used to receive the Hammer.js event and now receive the native <code>PointerEvent</code> too.</p><h2 id="wheel-zoom-follows-the-scrolled-distance" tabindex="-1">Wheel zoom follows the scrolled distance <a class="header-anchor" href="#wheel-zoom-follows-the-scrolled-distance" aria-label="Permalink to &quot;Wheel zoom follows the scrolled distance&quot;">​</a></h2><p>The wheel handler used to zoom by <code>speed</code> for every wheel event, whatever its size. It now zooms in proportion to the distance scrolled (the event&#39;s <code>deltaY</code>), reaching <code>speed</code> at 24 pixels and never exceeding it for one event. A notch of a mouse wheel is a longer distance than that and zooms by <code>speed</code> as before; a trackpad, which sends many small events, zooms more slowly and more smoothly. If you lowered <code>speed</code> to tame a trackpad, you may want to raise it again.</p><h2 id="package-layout" tabindex="-1">Package layout <a class="header-anchor" href="#package-layout" aria-label="Permalink to &quot;Package layout&quot;">​</a></h2><ul><li><p>The package is an ES module package (<code>&quot;type&quot;: &quot;module&quot;</code>) with an <code>exports</code> map. Only the package root can be imported; deep imports such as <code>chartjs-plugin-zoom/dist/...</code> or <code>chartjs-plugin-zoom/types/...</code> no longer resolve. Script tags and CDN URLs pointing at <code>dist/chartjs-plugin-zoom.min.js</code> are unaffected.</p></li><li><p><code>require(&#39;chartjs-plugin-zoom&#39;)</code> returns the same exports as the ES module instead of the plugin itself, and no longer registers the plugin:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Chart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;chart.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">zoomPlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;chartjs-plugin-zoom&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Chart.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(zoomPlugin);</span></span></code></pre></div></li><li><p>The published files are compiled to ES2022. Transpile them in your own build if you support older browsers.</p></li></ul><h2 id="typescript" tabindex="-1">TypeScript <a class="header-anchor" href="#typescript" aria-label="Permalink to &quot;TypeScript&quot;">​</a></h2><p>The plugin is now written in TypeScript and its declarations are generated from the sources.</p><ul><li>The type of <code>event</code> in <code>onPanStart</code> and <code>onPanRejected</code> is the gesture event described above rather than <code>HammerInput</code>, and <code>@types/hammerjs</code> is not installed with the plugin any more.</li><li>The <code>point</code> in <code>onZoomStart</code> and <code>onPanStart</code> is <code>{x: number, y: number}</code>. It is no longer typed as the Chart.js <code>Point</code>, whose coordinates can be <code>null</code> since Chart.js 4.5.</li><li>The option types, such as <code>ZoomPluginOptions</code>, are exported from the package root. Import them from <code>&#39;chartjs-plugin-zoom&#39;</code> instead of <code>&#39;chartjs-plugin-zoom/types/options&#39;</code>.</li></ul>`,17)])])}const k=t(o,[["render",n]]);export{g as __pageData,k as default};
